package org.dextur.reputation.storage;

import java.nio.file.Path;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.dextur.reputation.api.*;
import org.dextur.reputation.application.*;
import org.dextur.reputation.domain.investigation.InvestigationData.*;
import org.dextur.reputation.domain.protection.ProtectionData.Status;
import static org.junit.jupiter.api.Assertions.*;

final class InvestigationContract {
    enum Scenario { INSPECT, ACTIVE, REPLACED, RESTORE, ILLEGAL_RESTORE, DUPLICATE, CONFLICT, PENDING_APPROVE, PENDING_REJECT, PENDING_INVALIDATE_RESTORE, RECALCULATE, TRUST, FLAG, RELATIONS, DRY_RUN, FRACTIONAL_PLAN, BULK, OVERLAP, CANCEL, CONCURRENT_INVALIDATE, CONCURRENT_REPLACE, CONCURRENT_RESTORE, CONCURRENT_APPROVE, CONCURRENT_ADMIN_RECALCULATE, CONCURRENT_TRUST_VOTE, CONCURRENT_BULK_VOTE, CONCURRENT_BULKS, LEGACY_AUDIT, FILTERS, STALE, LEGACY_REVIEW_RESTORE, MIXED_REVIEW_RESTORE, LEGACY }
    static final Instant NOW=ProtectionFixtures.NOW.plusSeconds(300);static final UUID VOTER=UUID.fromString("00000000-0000-0000-0000-000000000111"),TARGET=UUID.fromString("00000000-0000-0000-0000-000000000222");
    static void configure(StorageBackend b,Path path)throws Exception{b.protection(ProtectionFixtures.rules(path,true));b.tiers(TierConfiguration.load(path));b.recovery(RecoveryConfiguration.load(path));b.features(PolicyConfiguration.load(path));b.investigation(AdministrationConfiguration.load(path));}
    static Request request(Action action,UUID subject){return new Request(UUID.randomUUID(),"global",action,subject,"CONSOLE","Test moderation",-1,"",NOW);}
    static VoteEntry cast(StorageBackend b,UUID voter,VoteType type,Instant now)throws Exception{return b.vote("global",ProtectionFixtures.vote(voter,TARGET,type,"moderation "+now),type==VoteType.NEGATIVE?ProtectionFixtures.young():ProtectionFixtures.mature(),ProtectionFixtures.eligibility(),now).entry();}
    static Query query(Section section,UUID player,UUID id){return new Query(section,"global",player,id,Filter.empty(),1,14);}
    static void run(Scenario scenario,StorageBackend b,Path path)throws Exception {
        if(scenario==Scenario.LEGACY){b.tiers(TierConfiguration.load(path));var vote=cast(b,VOTER,VoteType.POSITIVE,NOW);configure(b,path);assertEquals(1,b.getOrCreate(TARGET,"global").visibleScore());b.moderate(request(Action.INVALIDATE,vote.operationId()));assertEquals(0,b.getOrCreate(TARGET,"global").visibleScore());b.moderate(request(Action.RESTORE,vote.operationId()));assertEquals(1,b.getOrCreate(TARGET,"global").visibleScore());return;}
        configure(b,path);var vote=cast(b,VOTER,VoteType.POSITIVE,NOW);var before=b.snapshot();
        switch(scenario){
            case INSPECT->{var overview=b.investigate(query(Section.INSPECT,TARGET,null));assertEquals("0",overview.summary().get("community"));assertEquals("0",overview.summary().get("administrative"));assertEquals(VOTER.toString(),b.investigate(query(Section.VOTE,null,vote.operationId())).rows().getFirst().values().get("voter"));assertThrows(Exception.class,()->b.investigate(query(Section.INSPECT,UUID.randomUUID(),null)));assertEquals(before,b.snapshot());}
            case ACTIVE->{b.moderate(request(Action.INVALIDATE,vote.operationId()));assertEquals(0,b.getOrCreate(TARGET,"global").visibleScore());assertEquals(0,b.snapshot().protection().scores().getFirst().currentUnits());assertEquals(VoteProcessingOutcome.Status.INVALIDATED,b.outcome(vote.operationId()).status());assertEquals(before.votes(),b.snapshot().votes());assertEquals(before.protection().trusts(),b.snapshot().protection().trusts());}
            case REPLACED->{cast(b,VOTER,VoteType.POSITIVE,NOW.plusSeconds(1));long score=b.getOrCreate(TARGET,"global").visibleScore();b.moderate(request(Action.INVALIDATE,vote.operationId()));assertEquals(score,b.getOrCreate(TARGET,"global").visibleScore());assertThrows(Exception.class,()->b.moderate(request(Action.RESTORE,vote.operationId())));}
            case RESTORE->{b.moderate(request(Action.INVALIDATE,vote.operationId()));b.moderate(request(Action.RESTORE,vote.operationId()));assertEquals(350000,b.snapshot().protection().scores().getFirst().currentUnits());assertEquals(2,b.snapshot().investigation().records().stream().filter(r->r.kind()==Kind.AUDIT).count());}
            case ILLEGAL_RESTORE->{assertThrows(Exception.class,()->b.moderate(request(Action.RESTORE,vote.operationId())));b.moderate(request(Action.INVALIDATE,vote.operationId()));cast(b,VOTER,VoteType.POSITIVE,NOW.plusSeconds(1));assertThrows(Exception.class,()->b.moderate(request(Action.RESTORE,vote.operationId())));}
            case DUPLICATE->{var r=request(Action.INVALIDATE,vote.operationId());b.moderate(r);var after=b.snapshot();assertTrue(b.moderate(new Request(r.operation(),r.scope(),r.action(),r.subject(),r.actor(),r.reason(),-1,"",NOW.plusSeconds(1))).duplicate());assertEquals(after,b.snapshot());assertEquals("NO_CHANGE",b.moderate(request(Action.INVALIDATE,vote.operationId())).status());}
            case CONFLICT->{var r=request(Action.INVALIDATE,vote.operationId());b.moderate(r);assertThrows(Exception.class,()->b.moderate(new Request(r.operation(),r.scope(),Action.RESTORE,r.subject(),r.actor(),r.reason(),-1,"",NOW)));}
            case PENDING_APPROVE,PENDING_REJECT,PENDING_INVALIDATE_RESTORE,CONCURRENT_APPROVE->{cast(b,UUID.randomUUID(),VoteType.NEGATIVE,NOW);var pending=cast(b,UUID.randomUUID(),VoteType.NEGATIVE,NOW);assertEquals(Status.PENDING,b.inspectVote(pending.operationId()).status());if(scenario==Scenario.PENDING_APPROVE){b.moderate(request(Action.APPROVE,pending.operationId()));assertEquals(Status.ACCEPTED,b.inspectVote(pending.operationId()).status());}else if(scenario==Scenario.PENDING_REJECT){b.moderate(request(Action.REJECT,pending.operationId()));assertEquals(Status.INVALIDATED,b.inspectVote(pending.operationId()).status());}else if(scenario==Scenario.PENDING_INVALIDATE_RESTORE){b.moderate(request(Action.INVALIDATE,pending.operationId()));b.moderate(request(Action.RESTORE,pending.operationId()));assertEquals(Status.PENDING,b.inspectVote(pending.operationId()).status());}else{race(()->{try{return b.moderate(request(Action.APPROVE,pending.operationId()));}catch(IllegalStateException e){assertEquals("INV_PENDING",e.getMessage());return null;}},()->b.moderate(request(Action.INVALIDATE,pending.operationId())));assertEquals(Status.INVALIDATED,b.inspectVote(pending.operationId()).status());}}
            case RECALCULATE->{b.administer(PolicyContract.admin(TARGET,org.dextur.reputation.domain.policy.AdministrationData.Type.SET,100,NOW));var r=request(Action.RECALCULATE_ALL,TARGET);b.moderate(r);assertEquals(100,b.getOrCreate(TARGET,"global").visibleScore());assertEquals(before.votes(),b.snapshot().votes());assertTrue(b.moderate(r).duplicate());}
            case TRUST->{var old=b.inspectTrust(VOTER,"global");b.moderate(request(Action.RECALCULATE_TRUST,VOTER));assertTrue(b.inspectTrust(VOTER,"global").revision()>old.revision());var history=b.investigate(query(Section.TRUST_HISTORY,VOTER,null));assertTrue(history.rows().stream().anyMatch(row->row.values().get("action").equals("VOTE")));assertTrue(history.rows().stream().anyMatch(row->row.values().get("action").equals("RECALCULATE_TRUST")));var p=b.getOrCreate(VOTER,"global");assertThrows(Exception.class,()->b.moderate(new Request(UUID.randomUUID(),"global",Action.RECALCULATE_TRUST,VOTER,"CONSOLE","stale",old.revision(),"",NOW)));}
            case FLAG->{cast(b,UUID.randomUUID(),VoteType.NEGATIVE,NOW);cast(b,UUID.randomUUID(),VoteType.NEGATIVE,NOW);var flags=b.investigate(query(Section.FLAGS,TARGET,null));assertFalse(flags.rows().isEmpty());UUID id=flags.rows().getFirst().id();b.moderate(new Request(UUID.randomUUID(),"global",Action.RESOLVE_FLAG,id,"CONSOLE","False positive",1,"FALSE_POSITIVE",NOW));assertTrue(b.investigate(query(Section.FLAGS,TARGET,null)).rows().stream().anyMatch(r->r.id().equals(id)&&r.values().get("status").equals("FALSE_POSITIVE")));assertEquals(0,b.inspectTrust(VOTER,"global").confirmed());}
            case RELATIONS->{var report=b.investigate(query(Section.RELATIONS,TARGET,null));assertEquals("CORRELATION_ONLY",report.summary().get("evidence"));assertEquals(1,report.rows().size());}
            case DRY_RUN->{var plan=b.plan(Action.INVALIDATE,"global",new Filter(VOTER,null,null,"",null,null,"","",null),"CONSOLE","Plan",NOW);assertEquals(List.of(vote.operationId()),plan.subjects());assertEquals(before,b.snapshot());}
            case FRACTIONAL_PLAN->{cast(b,UUID.randomUUID(),VoteType.POSITIVE,NOW);assertEquals(1,b.getOrCreate(TARGET,"global").visibleScore());var plan=b.plan(Action.INVALIDATE,"global",new Filter(VOTER,TARGET,null,"",null,null,"","",null),"CONSOLE","Exact dry run",NOW);assertEquals(-1,plan.deltas().get(TARGET.toString()));UUID operation=UUID.randomUUID();b.begin(operation,plan,NOW);b.advance(operation,"CONSOLE",false,NOW);assertEquals(0,b.getOrCreate(TARGET,"global").visibleScore());}
            case BULK,OVERLAP,CANCEL->{var filter=new Filter(null,TARGET,null,"",null,null,"","",null);var plan=b.plan(Action.INVALIDATE,"global",filter,"CONSOLE","Bulk",NOW);UUID id=UUID.randomUUID();b.begin(id,plan,NOW);if(scenario==Scenario.CANCEL){assertEquals("CANCELLED",b.advance(id,"CONSOLE",true,NOW).operation().status());assertEquals(before.votes(),b.snapshot().votes());}else{assertEquals("COMPLETED",b.advance(id,"CONSOLE",false,NOW).operation().status());assertTrue(b.advance(id,"CONSOLE",false,NOW).mutations().isEmpty());if(scenario==Scenario.OVERLAP)assertThrows(Exception.class,()->b.begin(UUID.randomUUID(),plan,NOW));}}
            case CONCURRENT_INVALIDATE->{race(()->b.moderate(request(Action.INVALIDATE,vote.operationId())),()->b.moderate(request(Action.INVALIDATE,vote.operationId())));assertEquals(0,b.snapshot().protection().scores().getFirst().currentUnits());}
            case CONCURRENT_REPLACE->{race(()->b.moderate(request(Action.INVALIDATE,vote.operationId())),()->cast(b,VOTER,VoteType.POSITIVE,NOW.plusSeconds(1)));assertEquals(350000,b.snapshot().protection().scores().getFirst().currentUnits());}
            case CONCURRENT_RESTORE->{b.moderate(request(Action.INVALIDATE,vote.operationId()));race(()->b.moderate(request(Action.RESTORE,vote.operationId())),()->b.moderate(request(Action.INVALIDATE,vote.operationId())));assertTrue(Set.of(0L,350000L).contains(b.snapshot().protection().scores().getFirst().currentUnits()));}
            case CONCURRENT_TRUST_VOTE->{race(()->b.moderate(request(Action.RECALCULATE_TRUST,VOTER)),()->cast(b,VOTER,VoteType.POSITIVE,NOW.plusSeconds(1)));assertEquals(2,b.inspectTrust(VOTER,"global").submitted());}
            case CONCURRENT_BULK_VOTE,CONCURRENT_BULKS->{var plan=b.plan(Action.INVALIDATE,"global",new Filter(null,TARGET,null,"",null,null,"","",null),"CONSOLE","Bulk race",NOW);UUID first=UUID.randomUUID();b.begin(first,plan,NOW);if(scenario==Scenario.CONCURRENT_BULKS){UUID second=UUID.randomUUID();b.begin(second,plan,NOW);race(()->b.advance(first,"CONSOLE",false,NOW),()->b.advance(second,"CONSOLE",false,NOW));assertEquals(0,b.snapshot().protection().scores().getFirst().currentUnits());}else{race(()->b.advance(first,"CONSOLE",false,NOW),()->cast(b,VOTER,VoteType.POSITIVE,NOW.plusSeconds(1)));assertEquals(350000,b.snapshot().protection().scores().getFirst().currentUnits());}}
            case LEGACY_REVIEW_RESTORE->{var evaluation=b.inspectVote(vote.operationId());b.review(UUID.randomUUID(),vote.operationId(),UUID.randomUUID(),"Legacy moderator",org.dextur.reputation.domain.protection.ProtectionData.Review.INVALIDATE,evaluation.revision(),NOW);assertEquals(VoteProcessingOutcome.Status.INVALIDATED,b.outcome(vote.operationId()).status());b.moderate(request(Action.RESTORE,vote.operationId()));assertEquals(VoteProcessingOutcome.Status.ACCEPTED,b.outcome(vote.operationId()).status());assertEquals(350000,b.snapshot().protection().scores().getFirst().currentUnits());}
            case MIXED_REVIEW_RESTORE->{cast(b,UUID.randomUUID(),VoteType.NEGATIVE,NOW);var pending=cast(b,UUID.randomUUID(),VoteType.NEGATIVE,NOW);assertEquals(Status.PENDING,b.inspectVote(pending.operationId()).status());b.moderate(request(Action.REJECT,pending.operationId()));b.moderate(request(Action.RESTORE,pending.operationId()));var a=b.inspectVote(pending.operationId());b.review(UUID.randomUUID(),pending.operationId(),UUID.randomUUID(),"Legacy approval",org.dextur.reputation.domain.protection.ProtectionData.Review.ACCEPT,a.revision(),NOW);a=b.inspectVote(pending.operationId());b.review(UUID.randomUUID(),pending.operationId(),UUID.randomUUID(),"Legacy invalidation",org.dextur.reputation.domain.protection.ProtectionData.Review.INVALIDATE,a.revision(),NOW);b.moderate(request(Action.RESTORE,pending.operationId()));assertEquals(Status.ACCEPTED,b.inspectVote(pending.operationId()).status());assertEquals(-350000,b.snapshot().protection().scores().stream().filter(row->row.player().equals(TARGET)).findFirst().orElseThrow().currentUnits());}
            case LEGACY_AUDIT->{var request=PolicyContract.admin(TARGET,org.dextur.reputation.domain.policy.AdministrationData.Type.ADD,1,NOW);b.administer(request);assertFalse(b.investigate(query(Section.AUDIT,TARGET,null)).rows().isEmpty());assertFalse(b.investigate(query(Section.OPERATION,null,request.operation())).rows().isEmpty());}
            case FILTERS->{cast(b,UUID.randomUUID(),VoteType.NEGATIVE,NOW);var pending=cast(b,UUID.randomUUID(),VoteType.NEGATIVE,NOW);assertEquals(Status.PENDING,b.inspectVote(pending.operationId()).status());var query=new Query(Section.PENDING,"global",null,null,new Filter(pending.voterId(),TARGET,VoteType.NEGATIVE,"",NOW.plusSeconds(1),NOW.minusSeconds(1),"HIGH","NEGATIVE_SPIKE",null),1,1);assertEquals(List.of(pending.operationId()),b.investigate(query).rows().stream().map(Row::id).toList());var search=new Query(Section.VOTES,"global",TARGET,null,new Filter(null,TARGET,null,"",null,null,"","",null,"moderation"),1,14);assertEquals(3,b.investigate(search).rows().size());assertTrue(b.investigate(new Query(Section.VOTES,"global",TARGET,null,new Filter(null,TARGET,null,"",null,null,"","",null,"MODERATION"),1,14)).rows().isEmpty());var flag=b.investigate(query(Section.FLAGS,TARGET,null)).rows().stream().filter(row->row.values().get("source").equals("NEGATIVE_SPIKE")).findFirst().orElseThrow();b.moderate(new Request(UUID.randomUUID(),"global",Action.RESOLVE_FLAG,flag.id(),"CONSOLE","False filter check",Long.parseLong(flag.values().get("revision")),"FALSE_POSITIVE",NOW));assertEquals(1,b.investigate(new Query(Section.FLAGS,"global",TARGET,null,new Filter(null,null,null,"FALSE_POSITIVE",null,null,"HIGH","NEGATIVE_SPIKE",null,"False filter check"),1,14)).total());assertEquals(1,b.investigate(new Query(Section.AUDIT,"global",TARGET,null,new Filter(null,null,null,"",null,null,"","",null,"False filter check"),1,14)).rows().size());assertThrows(Exception.class,()->new Filter(null,null,null,"BOGUS",null,null,"","",null));}
            case STALE->{long revision=Long.parseLong(b.investigate(query(Section.VOTE,null,vote.operationId())).rows().getFirst().values().get("revision"));b.moderate(request(Action.INVALIDATE,vote.operationId()));assertThrows(Exception.class,()->b.moderate(new Request(UUID.randomUUID(),"global",Action.RESTORE,vote.operationId(),"CONSOLE","stale",revision,"",NOW)));}
            case CONCURRENT_ADMIN_RECALCULATE->{race(()->b.administer(PolicyContract.admin(TARGET,org.dextur.reputation.domain.policy.AdministrationData.Type.SET,100,NOW)),()->b.moderate(request(Action.RECALCULATE_REPUTATION,TARGET)));assertEquals(100,b.getOrCreate(TARGET,"global").visibleScore());}
            default->throw new AssertionError(scenario);
        }
        var snapshot=b.snapshot();assertEquals(snapshot,new SnapshotCodec().decode(new SnapshotCodec().encode(99,snapshot)).snapshot());
    }
    interface Work{Object run()throws Exception;}
    static void race(Work first,Work second)throws Exception{var barrier=new CyclicBarrier(2);try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->{barrier.await();return first.run();});var b=pool.submit(()->{barrier.await();return second.run();});a.get(30,TimeUnit.SECONDS);b.get(30,TimeUnit.SECONDS);}}
}
